        EXEC sp_executesql @_Sql;
        PRINT N'  Column ' + ISNULL(@_Cc, N'?') + N' rows removed: ' + CAST(@@ROWCOUNT AS NVARCHAR(20));
        SET @_i = @_i + 1;
    END;
