        FETCH NEXT FROM mycur INTO @valEmployeeID;
    END;

    CLOSE mycur;
    DEALLOCATE mycur;

    PRINT N'Step 2: Check for orphans in Security_GroupUsers (before re-enable)...';
    SET @_Ct = NULL;
    SELECT @_Cs = OBJECT_SCHEMA_NAME(fk.parent_object_id), @_Ct = OBJECT_NAME(fk.parent_object_id),
           @_Cc = COL_NAME(fkc.parent_object_id, fkc.parent_column_id),
           @_Rs = OBJECT_SCHEMA_NAME(fk.referenced_object_id), @_Rt = OBJECT_NAME(fk.referenced_object_id),
           @_Rk = COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id)
    FROM sys.foreign_keys fk
    INNER JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id
    WHERE fk.name LIKE N'FK_Security_GroupUsers_Security_Users%'
       OR (OBJECT_NAME(fk.parent_object_id) = N'Security_GroupUsers' AND OBJECT_NAME(fk.referenced_object_id) = N'Security_Users');
    IF @_Ct IS NOT NULL
    BEGIN
        SET @_Sql = N'SELECT @o = COUNT(*) FROM ' + QUOTENAME(@_Cs) + N'.' + QUOTENAME(@_Ct) + N' sg WHERE NOT EXISTS (SELECT 1 FROM ' + QUOTENAME(@_Rs) + N'.' + QUOTENAME(@_Rt) + N' su WHERE su.' + QUOTENAME(@_Rk) + N' = sg.' + QUOTENAME(@_Cc) + N')';
        EXEC sp_executesql @_Sql, N'@o INT OUTPUT', @o = @_Orphan OUTPUT;
        PRINT N'Security_GroupUsers orphan count (must be 0): ' + CAST(@_Orphan AS NVARCHAR(20));
        IF @_Orphan > 0
        BEGIN
            CREATE TABLE #FkOrphans (seq INT IDENTITY(1,1), Cs SYSNAME, Ct SYSNAME, Cc SYSNAME, Rs SYSNAME, Rt SYSNAME, Rk SYSNAME);
            INSERT INTO #FkOrphans SELECT OBJECT_SCHEMA_NAME(fk.parent_object_id), OBJECT_NAME(fk.parent_object_id), CAST(COL_NAME(fkc.parent_object_id, fkc.parent_column_id) AS NVARCHAR(128)), OBJECT_SCHEMA_NAME(fk.referenced_object_id), OBJECT_NAME(fk.referenced_object_id), CAST(COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id) AS NVARCHAR(128)) FROM sys.foreign_keys fk INNER JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id WHERE fk.name LIKE N'FK_Security_GroupUsers_Security_Users%' OR (OBJECT_NAME(fk.parent_object_id) = N'Security_GroupUsers' AND OBJECT_NAME(fk.referenced_object_id) = N'Security_Users');
            SET @_i = 1;
            SET @_max = (SELECT COUNT(*) FROM #FkOrphans);
            WHILE @_i <= @_max
            BEGIN
                SELECT @_Cs = Cs, @_Ct = Ct, @_Cc = Cc, @_Rs = Rs, @_Rt = Rt, @_Rk = Rk FROM #FkOrphans WHERE seq = @_i;
                SET @_Sql = N'DELETE FROM ' + QUOTENAME(@_Cs) + N'.' + QUOTENAME(@_Ct) + N' WHERE ' + QUOTENAME(@_Cc) + N' NOT IN (SELECT ' + QUOTENAME(@_Rk) + N' FROM ' + QUOTENAME(@_Rs) + N'.' + QUOTENAME(@_Rt) + N')';
                EXEC sp_executesql @_Sql;
                PRINT N'  Deleted orphans (FK col ' + ISNULL(@_Cc, N'?') + N'): ' + CAST(@@ROWCOUNT AS NVARCHAR(20));
                SET @_i = @_i + 1;
            END;
            DROP TABLE #FkOrphans;
            PRINT N'Orphan rows removed. Proceeding to re-enable constraints.';
        END
    END
    PRINT N'Step 2b: Clean FK orphans CHI cac FK tham chieu bang trong #TablesWeDeleteFrom (tranh xoa orphan khong lien quan nv nhu TIM_DayOffs->TIM_TimeSheets)...';
    CREATE TABLE #AllFk (seq INT IDENTITY(1,1), Ps SYSNAME, Pt SYSNAME, Pc SYSNAME, Rs SYSNAME, Rt SYSNAME, Rk SYSNAME);
    INSERT INTO #AllFk (Ps, Pt, Pc, Rs, Rt, Rk)
    SELECT OBJECT_SCHEMA_NAME(fk.parent_object_id), OBJECT_NAME(fk.parent_object_id), CAST(COL_NAME(fkc.parent_object_id, fkc.parent_column_id) AS NVARCHAR(128)),
           OBJECT_SCHEMA_NAME(fk.referenced_object_id), OBJECT_NAME(fk.referenced_object_id), CAST(COL_NAME(fkc.referenced_object_id, fkc.referenced_column_id) AS NVARCHAR(128))
    FROM sys.foreign_keys fk
    INNER JOIN sys.foreign_key_columns fkc ON fk.object_id = fkc.constraint_object_id
    WHERE fk.referenced_object_id IN (SELECT OBJECT_ID(QUOTENAME(SchemaName) + N'.' + QUOTENAME(TableName)) FROM #TablesWeDeleteFrom);
    SET @_max = (SELECT COUNT(*) FROM #AllFk);
    SET @_Pass = 0; SET @_TotalRemoved = 1;
    WHILE @_TotalRemoved > 0 AND @_Pass < 10
    BEGIN
        SET @_Pass = @_Pass + 1; SET @_TotalRemoved = 0; SET @_i = 1;
        IF @_Pass > 1 PRINT N'  Step 2b pass ' + CAST(@_Pass AS NVARCHAR(5)) + N' (xoa orphan moi phat sinh)...';
        WHILE @_i <= @_max
        BEGIN
            SELECT @_Cs = Ps, @_Ct = Pt, @_Cc = Pc, @_Rs = Rs, @_Rt = Rt, @_Rk = Rk FROM #AllFk WHERE seq = @_i;
            SET @_Sql = N'DELETE FROM ' + QUOTENAME(@_Cs) + N'.' + QUOTENAME(@_Ct) + N' WHERE ' + QUOTENAME(@_Cc) + N' IS NOT NULL AND ' + QUOTENAME(@_Cc) + N' NOT IN (SELECT ' + QUOTENAME(@_Rk) + N' FROM ' + QUOTENAME(@_Rs) + N'.' + QUOTENAME(@_Rt) + N' WHERE ' + QUOTENAME(@_Rk) + N' IS NOT NULL)';
            BEGIN TRY
                EXEC sp_executesql @_Sql;
                SET @_Orphan = @@ROWCOUNT;
                SET @_TotalRemoved = @_TotalRemoved + @_Orphan;
                IF @_Orphan > 0
                    PRINT N'  Orphans removed: ' + QUOTENAME(@_Ct) + N'.' + QUOTENAME(@_Cc) + N' (refs ' + QUOTENAME(@_Rt) + N'): ' + CAST(@_Orphan AS NVARCHAR(20)) + N' row(s)';
                ELSE IF @_i % 50 = 0
                    PRINT N'  Step 2b: checked ' + CAST(@_i AS NVARCHAR(10)) + N' / ' + CAST(@_max AS NVARCHAR(10)) + N' FKs...';
            END TRY
            BEGIN CATCH
                PRINT N'  Skip (error): ' + QUOTENAME(@_Ct) + N'.' + QUOTENAME(@_Cc) + N': ' + ERROR_MESSAGE();
            END CATCH
            SET @_i = @_i + 1;
        END;
        IF @_TotalRemoved > 0 PRINT N'  Step 2b pass ' + CAST(@_Pass AS NVARCHAR(5)) + N' total removed: ' + CAST(@_TotalRemoved AS NVARCHAR(20)) + N' row(s).';
    END;
    DROP TABLE #AllFk;
    PRINT N'Step 2b done (' + CAST(@_Pass AS NVARCHAR(5)) + N' pass(es), ' + CAST(@_max AS NVARCHAR(10)) + N' FKs per pass).';
    PRINT N'Step 3: Re-enabling constraints CHI cac bang trong #TablesWeDeleteFrom...';
    DECLARE curReenable CURSOR LOCAL FAST_FORWARD FOR SELECT QUOTENAME(SchemaName) + N'.' + QUOTENAME(TableName) FROM #TablesWeDeleteFrom ORDER BY SchemaName, TableName;
    OPEN curReenable;
    FETCH NEXT FROM curReenable INTO @_Tbl;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @_Sql = N'ALTER TABLE ' + @_Tbl + N' WITH CHECK CHECK CONSTRAINT ALL'; EXEC sp_executesql @_Sql;
        FETCH NEXT FROM curReenable INTO @_Tbl;
    END;
    CLOSE curReenable; DEALLOCATE curReenable;
    PRINT N'Step 3a: Re-enabling triggers (chi cac bang trong #TablesWeDeleteFrom)...';
    DECLARE curTrig CURSOR LOCAL FAST_FORWARD FOR SELECT QUOTENAME(SchemaName) + N'.' + QUOTENAME(TableName) FROM #TablesWeDeleteFrom ORDER BY SchemaName, TableName;
    OPEN curTrig;
    FETCH NEXT FROM curTrig INTO @_Tbl;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @_Sql = N'ALTER TABLE ' + @_Tbl + N' ENABLE TRIGGER ALL'; EXEC sp_executesql @_Sql;
        FETCH NEXT FROM curTrig INTO @_Tbl;
    END;
    CLOSE curTrig; DEALLOCATE curTrig;

    COMMIT TRANSACTION;
    PRINT N'DeleteEmployee: Done. COMMIT.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    BEGIN TRY
        EXEC sp_MSforeachtable 'ALTER TABLE ? WITH CHECK CHECK CONSTRAINT ALL';
        EXEC sp_MSforeachtable 'ALTER TABLE ? ENABLE TRIGGER ALL';
    END TRY BEGIN CATCH END CATCH;
    DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
    PRINT N'DeleteEmployee: Error - ROLLBACK. Message: ' + @ErrMsg;
    THROW;
END CATCH;